CREATE TABLE history_plans(id uuid PRIMARY KEY REFERENCES jobs(id) ON DELETE CASCADE,owner_id uuid NOT NULL REFERENCES users(id),body jsonb NOT NULL,status text NOT NULL DEFAULT 'running' CHECK(status IN ('running','paused','completed','cancelled','needs_attention')),revision bigint NOT NULL DEFAULT 0,symbol_no int NOT NULL DEFAULT 0,interval_no int NOT NULL DEFAULT 0,next_start timestamptz NOT NULL,child_job uuid,completed_chunks bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,id));
CREATE INDEX history_plans_owner ON history_plans(owner_id,created_at DESC,id DESC);
